import '@servicenow/sdk/global'
import { Flow, trigger, wfa, action } from '@servicenow/sdk/automation'

// =============================================================================
// Test Flow: WaitForADuration and Action without any datapills
// Tests that uuid cleanup works even when no datapill transformations occur
// =============================================================================
export const flowUuidCleanupNoDatapills = Flow(
    {
        $id: Now.ID['flow-uuid-cleanup-no-datapills'],
        name: 'UUID Cleanup No Datapills',
        description: 'Tests uuid cleanup for WaitForADuration and Action without datapills',
        flowPriority: 'MEDIUM',
        runAs: 'system',
        runWithRoles: [],
    },
    wfa.trigger(
        trigger.record.created,
        { $id: Now.ID['uuid-cleanup-no-datapills-trigger'] },
        {
            table: 'incident',
            condition: '',
            run_on_extended: 'false',
            run_flow_in: 'background',
            run_when_user_list: [],
            run_when_setting: 'both',
            run_when_user_setting: 'any',
        }
    ),
    (_params) => {
        // Wait for 5 seconds - no datapill references to outputs
        wfa.flowLogic.waitForADuration({
            $id: Now.ID['uuid-cleanup-wait'],
            durationType: 'explicit_duration',
            duration: Duration({
                days: 0,
                hours: 0,
                minutes: 0,
                seconds: 5,
            }),
        })

        // Log action with static values - no datapill references
        wfa.action(
            action.core.log,
            {
                $id: Now.ID['uuid-cleanup-log'],
            },
            {
                log_level: 'info',
                log_message: 'This is a static log message with no datapills',
            }
        )
    }
)
